const fs   = require\('fs'\);
const zlib = require\('zlib'\);
const W = 1200, H = 630;
const R = 42, G = 95, B = 62; // forest-700

const crcTable = new Uint32Array\(256\);
for \(let n = 0; n < 256; n++\) {
  let c = n;
  for \(let k = 0; k < 8; k++\) c = \(c & 1\) ? \(0xedb88320 ^ \(c >>> 1\)\) : \(c >>> 1\);
  crcTable[n] = c >>> 0;
}
function crc32\(buf\) {
  let c = 0xffffffff;
  for \(let i = 0; i < buf.length; i++\) c = \(crcTable[\(c ^ buf[i]\) & 0xff] ^ \(c >>> 8\)\) >>> 0;
  return \(c ^ 0xffffffff\) >>> 0;
}
function chunk\(type, data\) {
  const lb = Buffer.allocUnsafe\(4\); lb.writeUInt32BE\(data.length\);
  const tb = Buffer.from\(type, 'ascii'\);
  const cb = Buffer.allocUnsafe\(4\); cb.writeUInt32BE\(crc32\(Buffer.concat\([tb, data]\)\)\);
  return Buffer.concat\([lb, tb, data, cb]\);
}
const ihdr = Buffer.allocUnsafe\(13\);
ihdr.writeUInt32BE\(W, 0\); ihdr.writeUInt32BE\(H, 4\);
ihdr[8]=8; ihdr[9]=2; ihdr[10]=0; ihdr[11]=0; ihdr[12]=0;

const row = Buffer.allocUnsafe\(1 + W * 3\);
row[0] = 0;
for \(let x = 0; x < W; x++\) { row[1+x*3]=R; row[2+x*3]=G; row[3+x*3]=B; }
const raw = Buffer.concat\(Array.from\({length:H}, \(\) => row\)\);
const idat = zlib.deflateSync\(raw, { level: 1 }\);

const png = Buffer.concat\([
  Buffer.from\([137,80,78,71,13,10,26,10]\),
  chunk\('IHDR', ihdr\),
  chunk\('IDAT', idat\),
  chunk\('IEND', Buffer.alloc\(0\)\),
]\);
fs.mkdirSync\('public', { recursive: true }\);
fs.writeFileSync\('public/og-default.png', png\);
console.log\('Created public/og-default.png \(' + png.length + ' bytes, ' + W + 'x' + H + '\)'\);
")
